"""Bounded lossless optimizer for character-prefix reuse in serialized rows."""

from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Optimize row and column permutations without changing source cell values."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Serialize one scalar as the evaluator does, converting scalar missing values to ''."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the common-prefix length using binary-searched C-level slice comparisons."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute exact ideal Trie reuse as LCP totals of lexicographically adjacent rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(
            cls._lcp(ordered[i - 1], ordered[i])
            for i in range(1, len(ordered))
        )

    @staticmethod
    def _repeat_mass(values) -> int:
        """Measure length-weighted ordered-pair repetition for a sequence of strings."""
        counts = {}
        lengths = {}
        for value in values:
            counts[value] = counts.get(value, 0) + 1
            if value not in lengths:
                lengths[value] = len(value)
        return sum(
            lengths[value] * count * (count - 1)
            for value, count in counts.items()
        )

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize each source row according to its row-specific column permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    @classmethod
    def _candidate(cls, cells, orders):
        """Serialize, score, and lexicographically arrange one complete candidate."""
        strings = cls._make_strings(cells, orders)
        score = cls._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row),
        )
        return score, strings, row_order

    def _block_orders(self, cells) -> List[List[int]]:
        """Build two global orders using bounded directed repeated concatenation blocks."""
        n, m = cells.shape
        if m <= 1:
            return [list(range(m))]

        # Individually frequent columns are the only pair endpoints considered.
        standalone = [
            (self._repeat_mass(cells[:, column]), column)
            for column in range(m)
        ]
        standalone.sort(key=lambda item: (-item[0], item[1]))
        eligible = [column for _, column in standalone[:min(24, m)]]

        # Use one deterministic sample, and compute all baseline masses on that
        # same sample so the directed gain is numerically comparable.
        sample_n = min(n, 2048)
        sample_values = {
            column: [cells[row, column] for row in range(sample_n)]
            for column in eligible
        }
        base = {
            column: self._repeat_mass(sample_values[column])
            for column in eligible
        }

        edges = []
        for left in eligible:
            left_values = sample_values[left]
            for right in eligible:
                if left == right:
                    continue
                joined = [
                    left_values[index] + sample_values[right][index]
                    for index in range(sample_n)
                ]
                gain = (
                    self._repeat_mass(joined)
                    - base[left]
                    - base[right]
                )
                if gain > 0:
                    edges.append((gain, left, right))

        edges.sort(key=lambda item: (-item[0], item[1], item[2]))

        used = set()
        blocks = []
        for gain, left, right in edges:
            if left in used or right in used:
                continue
            used.add(left)
            used.add(right)
            blocks.append((left, right, gain))

        blocks.sort(key=lambda item: (-item[2], item[0], item[1]))
        remaining = [
            column for _, column in standalone
            if column not in used
        ]

        forward = []
        for left, right, _ in blocks:
            forward.extend((left, right))
        forward.extend(remaining)

        reverse = []
        for left, right, _ in reversed(blocks):
            reverse.extend((left, right))
        reverse.extend(remaining)

        return [forward, reverse]

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Choose one repeated leading column and rank each group's remaining suffix."""
        n, m = cells.shape
        if m <= 1:
            return [list(range(m)) for _ in range(n)]

        lead = max(
            (
                (self._repeat_mass(cells[:, column]), -column, column)
                for column in range(m)
            ),
            key=lambda item: (item[0], item[1]),
        )[2]

        groups = {}
        for row in range(n):
            groups.setdefault(cells[row, lead], []).append(row)

        remaining = [column for column in range(m) if column != lead]
        result = [None] * n

        for rows in groups.values():
            ranked = []
            for column in remaining:
                values = [cells[row, column] for row in rows]
                ranked.append((self._repeat_mass(values), column))
            ranked.sort(key=lambda item: (-item[0], item[1]))
            order = [lead] + [column for _, column in ranked]
            for row in rows:
                result[row] = order[:]

        return result

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate two directed-block layouts and a conditional layout, returning the best."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        candidates = []
        for order in self._block_orders(cells):
            candidates.append([order[:] for _ in range(n)])
        candidates.append(self._conditional_orders(cells))

        best = None
        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0])
            choice = (score, tuple(-column for column in signature))
            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, strings, row_order, orders = best
        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            permutation = orders[source]
            output[destination, :] = [
                raw[source, column] for column in permutation
            ]
            column_orders.append([
                df.columns[column] for column in permutation
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders

